/**
 * TRENDARYO — 3D HERO FALLBACK + WATCHDOG
 * ---------------------------------------------------------------------------
 * A plain (non-module) script, so it runs even when the ES-module scene in
 * hero-3d-scene.js fails — e.g. no WebGL, a blocked CDN, or a slow network.
 *
 * It does two jobs:
 *   1. Fills the hero's fallback row with offline-safe product tiles (data
 *      URIs generated by products-data.js) so the hero never renders empty.
 *   2. Watches for the scene's 'hero-3d-ready' event. If it never arrives,
 *      the hero flips to `.is-fallback` and shows that row instead.
 *
 * Deferred in index.html; no dependencies of its own.
 * ---------------------------------------------------------------------------
 */
(function () {
  'use strict';

  var hero = document.getElementById('hero');
  var slot = document.getElementById('tr-hero-fallback');
  if (!hero || !slot) return;

  function buildFallback() {
    if (slot.children.length) return;
    var P = window.TrendaryoProducts;
    if (!P) return;
    var list = [];
    try { list = (window.TrendaryoHome && window.TrendaryoHome.ranked) || P.all(); } catch (e) { list = P.all(); }
    /* Every 2nd product, up to 5 — deterministic and always offline-safe. */
    for (var i = 0, n = 0; i < list.length && n < 5; i += 2, n++) {
      var img = document.createElement('img');
      img.src = P.tile(list[i]);
      img.alt = '';
      img.setAttribute('aria-hidden', 'true');
      img.loading = 'lazy';
      img.decoding = 'async';
      slot.appendChild(img);
    }
  }

  function showFallback() {
    if (hero.classList.contains('is-3d-ready')) return;
    buildFallback();
    hero.classList.add('is-fallback');
  }

  /* If the scene is ready, remove the fallback immediately. */
  hero.addEventListener('hero-3d-ready', function () {
    hero.classList.remove('is-fallback');
  });

  /* Watchdog: the scene must report in within 6s (covers a slow CDN fetch
     for three.js + the font). Anything longer is treated as unavailable. */
  var timer = setTimeout(showFallback, 6000);

  /* Build the tiles eagerly in the background so they are warm if needed. */
  if (window.TrendaryoProducts) buildFallback();
  else document.addEventListener('DOMContentLoaded', buildFallback);

  /* WebGL probe: if the browser can't do WebGL at all, fall back now
     instead of waiting out the watchdog. */
  try {
    var c = document.createElement('canvas');
    var ok = !!(window.WebGLRenderingContext &&
      (c.getContext('webgl') || c.getContext('experimental-webgl')));
    if (!ok) { clearTimeout(timer); showFallback(); }
  } catch (e) { clearTimeout(timer); showFallback(); }
})();
